mapper.select:
SELECT request_hash,business_no,state
FROM idempotency_request
WHERE actor_type='USER' AND actor_id=#{userId} AND operation='PLACE_ORDER' AND idempotency_key=#{idempotencyKey}

SELECT order_no,user_id,merchant_id,payment_no,reservation_no,quote_no,total_amount_cents,currency,status,stock_decision,stock_sync_status,fulfillment_lock,pay_deadline,created_at,close_phase
FROM orders
WHERE user_id=#{userId}
ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM orders
WHERE user_id=#{userId}

SELECT payload_hash
FROM order_payment_fact
WHERE event_id=#{eventId}

SELECT version
FROM orders
WHERE order_no=#{orderNo}
